#!/usr/bin/env bash
# Checks that a commit message follows Conventional Commits (https://www.conventionalcommits.org).
# Usage: check-commit-msg.sh <file with the message>   (commit-msg hook)
#        check-commit-msg.sh --text "<message>"          (CI)
set -euo pipefail

if [[ "${1:-}" == "--text" ]]; then
    message="$2"
else
    message="$(cat "$1")"
fi

# First line that is not a git comment
header="$(printf '%s\n' "$message" | grep -v '^#' | head -n 1)"

# Messages generated by git itself
if [[ "$header" =~ ^(Merge|Revert\ \"|fixup!|squash!|amend!) ]]; then
    exit 0
fi

types="feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert"
pattern="^($types)(\([a-z0-9-]+\))?!?: [^ ].*$"
max_length=100

if [[ "$header" =~ $pattern ]] && (( ${#header} <= max_length )); then
    exit 0
fi

cat >&2 <<MSG
Invalid commit message header:
    $header

Expected "<type>(<optional scope>): <description>", at most $max_length characters.
Types: ${types//|/, }
Examples:
    feat(kafka): add retry topic for failed messages
    fix: return 404 when the message does not exist
    docs: explain how to run Trivy
Breaking change: add "!" before the colon, e.g. "feat(api)!: rename fields".
MSG
exit 1
